import { card, type CardCopy } from './contentTypes';
export const middlewareEnglish: Record<string, CardCopy> = {
'mysql/basic': card('Indexes, transactions and slow queries', 'Match indexes to real queries, transactions to business invariants, and optimization claims to measured plans and load.', 'If most experience is MongoDB, identify transferable methods and the limits of actual MySQL work.',
'Start with query shape, data distribution and workload. Inspect the execution plan and distinguish scanning, sorting, locking and I/O costs.\n\nChoose indexes and transaction boundaries deliberately, then compare equivalent load. Additional indexes cost writes and memory; theoretical knowledge is not evidence of a production tuning result.',
['Order composite columns for equality, range and sorting needs.', 'EXPLAIN ANALYZE executes supported statements; assess its impact first.', 'More indexes generally increase write and maintenance cost.', 'Isolation and application idempotency solve different problems.'],
['Verify actual index use.', 'Avoid unassessed analysis or DDL on large tables.', 'Do not present other database experience as MySQL production work.'],
[['MySQL or MongoDB?', 'Compare relationships, transaction scope, query patterns and operational skills. Relational constraints and document aggregates offer different advantages; both require indexing and capacity planning.'], ['How can deep pagination be optimized?', 'Use cursor pagination with a stable ordered key, such as time plus unique ID, and a matching index. Specify concurrent-update behavior; arbitrary page jumps need another design.'], ['Is a covering index always better?', 'It reduces clustered-index lookups but adds storage, cache pressure and write amplification. Weigh column width, query frequency and read/write mix.'], ['Why might an index perform poorly?', 'Functions, conversions, leading wildcards, column order and selectivity affect plans. A scan may be the optimizer’s correct choice; inspect statistics and version-specific plans.'], ['Is online DDL impact-free?', 'No. Algorithms and lock levels vary by operation/version; metadata locks, space, resource demand and replication lag remain. Validate execution and recovery plans.']]),
'mysql/with-cache': card('Database and Redis caching', 'Caching reduces read load; update, expiry and recovery protocols determine freshness.', 'Resource queries and reporting: tie performance figures to verified measurement definitions.',
'Keep the database authoritative and define cache freshness, invalidation and fallback. Database-first updates reduce some stale-refill windows but do not guarantee strong consistency.\n\nBound fallback traffic and measure hit rate alongside database load, tail latency and errors. Local and shared caches each need capacity and expiry rules.',
['Rate-limit database fallback during cache failures.', 'Failed deletion and delayed stale refills are separate problems.', 'Local and Redis caches need separate freshness policies.', 'Interpret hit rate with source load and hotspot distribution.'],
['Write-then-delete is not strong consistency.', 'Avoid simultaneous unbounded fallback.', 'Do not quote unverified availability or cost percentages.'],
[['Why update the database before deleting cache?', 'Deleting first lets concurrent reads refill old data before the write. Committing first reduces this window, but failed invalidation and delayed refills still need handling.'], ['How is inconsistency bounded?', 'Choose TTLs, reliable invalidation, version checks or authoritative reads. Critical consistent decisions cannot rely solely on asynchronous caching; specify failure behavior.'], ['How do local and Redis caches combine?', 'Local caches reduce network cost; Redis shares across instances. Bound both, and retain TTL/version recovery because invalidation messages can be lost.'], ['How is improvement demonstrated?', 'Compare equivalent traffic/data using hit rate, database QPS, P95/P99, errors and resource cost. Record baseline and window to separate workload changes from cache effects.'], ['How should mass expiry be handled?', 'Use expiry jitter, request coalescing, limits and warming. Serve explicitly aged data only where allowed, while protecting database capacity.']]),
'mysql/isolation': card('Isolation / MVCC', 'InnoDB isolation affects snapshots and locks; consistent reads and locking reads require separate analysis.', 'Use mechanisms and controlled experiments; state whether production settings were actually changed.',
'MVCC selects visible record versions, while locking reads and writes also depend on indexes, ranges and isolation. RC generally refreshes consistent-read snapshots per statement; RR generally reuses the transaction snapshot.\n\nTest concrete interleavings. Isolation is not a substitute for unique constraints, idempotency or an explicit business transaction.',
['Consistent reads generally avoid row locks, but other locks still exist.', 'RC versus RR involves more than a phantom-read label.', 'Lock ranges depend on isolation, indexes and access paths.', 'Unique constraints protect uniqueness more reliably than check-then-insert.'],
['Not every SELECT uses the same snapshot.', 'MVCC does not eliminate write conflicts.', 'Validate workload effects before changing production isolation.'],
[['How do RR and RC differ?', "In InnoDB, Read Committed (RC) creates a fresh snapshot for each consistent read. Repeatable Read (RR) normally reuses the snapshot created by the first consistent read, or one explicitly taken at transaction start. For locking reads and updates under RR, the access path matters. An equality search on the full unique key that finds a row normally locks just that index record. Range scans normally take next-key locks, and a unique-key miss can still lock the relevant gap. RC avoids gap locks for ordinary searches and scans, but can still take them for foreign-key and duplicate-key checks."], ['How does MVCC supply snapshots?', 'Record versions, transaction visibility and undo information reconstruct eligible data. Long transactions retain history and increase cleanup pressure.'], ['Does RR eliminate all phantom problems?', "Separate consistent reads from locking reads. Consistent reads under RR reuse a snapshot, while locking range scans can use next-key locks. Mixing read types or crossing transactions does not guarantee unchanged business results."], ['How does this compare with MongoDB?', "Compare the actual read concern, write concern, topology and transaction scope. SQL isolation levels do not map one-to-one to MongoDB settings. Verify visibility and conflict handling with the specific read and write operations."], ['How should isolation issues be observed?', 'Use two controlled sessions to verify read, write, and commit order under RR and RC. In production, start with performance_schema.data_lock_waits. Match REQUESTING_ENGINE_LOCK_ID and BLOCKING_ENGINE_LOCK_ID to data_locks for index and lock mode, then check information_schema.INNODB_TRX for the blocking transaction and its age.']],
{scope:'Based on MySQL 8.4 / InnoDB; confirm other engines and versions separately.'}),
'mysql/deadlock': card('Deadlocks and lock waits', 'Deadlocks form cycles of transaction waits; reduce lock scope and standardize order, with bounded transaction retries.', 'Use sanitized deadlock evidence to explain ordering, fixes and regression results.',
'Reconstruct held and requested locks for every participating transaction. The chosen indexes and access order determine conflicts.\n\nRetry the appropriate transaction within a deadline and backoff budget. Database rollback does not undo remote side effects, so idempotency must cover the complete operation.',
['Actual execution paths determine locked records and ranges.', 'Short transactions reduce conflict windows but cannot eliminate deadlocks.', 'Bound retry count, total time and backoff.', 'External calls are not automatically protected by database rollback.'],
['Do not retry only the final failed statement blindly.', 'Unlimited retries amplify contention.', 'Not every lock wait is a deadlock.'],
[['How are deadlock logs read?', 'Use SHOW ENGINE INNODB STATUS for the latest detected deadlock. Compare the locks held and requested by the participants, the conflicting indexes, and the access order. To capture every deadlock, consider enabling innodb_print_all_deadlocks to write details to the error log. For current waits, check performance_schema.data_lock_waits.'], ['How many retries?', 'Choose a bounded count and total budget from request deadlines, conflict rates and capacity. Back off; persistent contention should produce a recognizable failure or asynchronous handling.'], ['How are retries made idempotent?', 'Constrain the operation key and state transactionally. Use remote idempotency or durable events for side effects; rollback cannot retract emails, payments or remote actions.'], ['How do timeouts differ from deadlocks?', "A deadlock is a wait cycle. InnoDB rolls back the entire victim transaction. A lock wait timeout means the wait exceeded its threshold. InnoDB normally rolls back only the current statement, unless innodb_rollback_on_timeout is enabled. Check or explicitly roll back any remaining transaction before deciding whether to retry."], ['Why do gap locks increase conflicts?', 'Range protection can block inserts into gaps. Inspect isolation and indexed predicates and narrow access ranges without discarding required consistency.']]),
'mysql/repl': card('Replication and read routing', 'Replication, failover and read/write routing are separate capabilities; replica reads need a consistency contract.', 'Explain replication mode, failover ownership and read visibility requirements.',
'Distinguish receiving replication logs from applying them. Replica lag and failover can expose stale reads or uncertain write outcomes.\n\nFence the old primary, validate candidate progress and handle broken connections with bounded retries. Read-your-writes may require primary routing or waiting for a known transaction.',
['Separate log-receive and apply lag.', 'GTIDs identify transactions; they do not perform safe failover.', 'Routing does not prevent two primaries from accepting writes.', 'Observe replication errors, queues, transactions and business visibility.'],
['Semisynchronous acknowledgement does not mean applied data.', 'One lag-in-seconds metric is insufficient.', 'Fence the old primary before reopening writes.'],
[['What do replica threads do?', 'Receivers fetch source logs into relay logs; appliers execute events, potentially in parallel. Names and parallelism vary by version; inspect status to locate bottlenecks.'], ['What if semisynchronous acknowledgement times out?', "A semisynchronous replica acknowledges after writing and flushing the events to its relay log, before application is required. On an acknowledgement timeout the source falls back to asynchronous replication and can return to semisynchronous operation once a replica catches up. Monitor the actual mode and timeouts, and assess loss risk for the relevant failures."], ['How should lag be monitored?', 'Combine receive/apply progress, errors, queues and heartbeats. Seconds_Behind_Source has limits; verify required changes using transaction IDs or business timestamps.'], ['What must applications handle during failover?', "Handle connection loss, address changes, uncertain commit outcomes and bounded retries. The failover system must fence the old source and check candidate progress. A network error alone cannot establish that the transaction failed to commit."], ['How can clients read their own writes?', 'Route relevant reads to the primary or wait for the replica to execute the required GTID. Define timeout fallback; fixed sleeps are not a consistency guarantee.']]),
'mysql/shard': card('Sharding', 'Sharding distributes data and load while adding cross-shard query, transaction and migration costs.', 'Distinguish design knowledge, test results and actual migration responsibility.',
'Confirm a capacity bottleneck before sharding. The key controls distribution and query routing; large tenants and hot keys can defeat otherwise balanced plans.\n\nVersion routes and migration state. Validate reads, writes and consistency at cutover; rollback requires reconciling any writes unique to the new shards.',
['Shard keys determine both balance and locality.', 'Global uniqueness needs coordination or a provable key design.', 'Manage routing versions and migration state reliably.', 'Plan for unusually large tenants and hotspots.'],
['Do not shard before identifying the bottleneck.', 'Validate reads and rollback as well as copied writes.', 'Scatter-gather cannot cheaply repair a poor shard key.'],
[['When should sharding be avoided?', 'First address poor queries, missing indexes, long transactions and uncontrolled retention. Capacity and growth evidence must justify added business and operational complexity.'], ['How is a shard key chosen?', 'Assess access paths, cardinality, distribution, growth and mutability. Tenant IDs provide locality but may need a large-tenant splitting or dedicated-capacity strategy.'], ['What about queries without the key?', 'Use a lookup index or separate read model to locate shards. Bound unavoidable fan-out, concurrency and result size; make global sort/pagination costs explicit.'], ['How are cross-shard transactions handled?', 'Reduce them through aggregate boundaries first. Where required, choose supported distributed transactions or state machines with compensation; compensation is not database rollback.'], ['How can migration be rolled back?', 'Validate incremental synchronization before cutover and specify post-cutover writes. New-only writes require reverse synchronization or reconciliation; switching the route back is insufficient.']]),
'mongo/mongo-idx': card('Indexes and staged queries', 'Match filtering, sorting and projection, then use explain to check scan amplification and execution cost.', 'CMDB query optimization: compare query shapes, indexes and examined records before and after.',
'Identify representative filters, sort order and returned fields before designing an index. Inspect examined keys/documents and sort behavior alongside latency under load.\n\nESR is a design guideline, not a universal ordering rule. Include index storage and write cost, and prefer stable cursor pagination for sequential browsing.',
['Support both filtering and sorting.', 'Coverage depends on projection and index restrictions.', 'Multikey indexes affect compound and covered-query behavior.', 'Include write and storage costs in evaluation.'],
['ESR is not an unconditional formula.', 'executionTimeMillis alone is insufficient.', 'Increasing skip indefinitely does not solve deep pagination.'],
[['What is a covered query?', 'The index satisfies conditions and returned fields without fetching documents. Check _id projection and multikey restrictions, then verify the plan.'], ['How are slow queries located?', 'Identify query shapes from slow logs/profiling, then inspect scans, sorting and waits. Check resource pressure, connection pools and replicas rather than only extending timeouts.'], ['How should ESR be applied?', "Start with Equality, Sort, Range (ESR) for compound indexes. A highly selective range can go before sort (ERS) when reducing the scan is worth an in-memory sort. Verify using the real predicates, sort requirements and execution statistics."], ['Why might an existing index underperform?', 'Check types, sort direction, cardinality and multikey behavior. Validate optimizer choices on representative data rather than permanently masking issues with hint.'], ['How should pagination work?', "Use a sort field plus unique ID as a cursor with a matching index. Specify concurrent-update behavior; arbitrary jumps and total counts may need separate read models."]]),
'mongo/mongo-txn': card('Transactions and boundaries', 'Single-document writes are atomic; multi-document transactions require explicit deployment, concern and retry semantics.', 'CMDB updates: identify invariants that require atomicity and side effects outside the transaction.',
'Choose document boundaries before expanding transaction scope. Read and write concerns determine visibility and acknowledgement, while distributed transactions add coordination cost.\n\nUse supported driver retry behavior. Transaction callbacks may run repeatedly; persist an outbox with business state and handle uncertain commit outcomes separately from definite failure.',
['Transactions add coordination cost and do not replace modeling.', 'Analyze majority acknowledgement with readConcern.', 'Retries may need to repeat the transaction’s reads and writes.', 'Commit outbox events in the same transaction as business changes.'],
['Do not issue irreversible remote actions inside retryable callbacks.', 'UnknownTransactionCommitResult is not definite failure.', 'Cross-shard transactions have latency and availability costs.'],
[['How should isolation be described?', "MongoDB supports multi-document transactions on replica sets and sharded clusters. With majority write concern at commit, snapshot read concern guarantees a snapshot of majority-committed data, synchronized across shards in a sharded cluster. Choose the concerns for the workload and verify visibility, conflicts and outcomes under failure."], ['How does this differ from MySQL?', 'Compare the same business invariant across models, locking/conflicts, concerns and coordination costs. The claim that MongoDB has no transactions is obsolete.'], ['How does an outbox work?', "Write the business update and the outgoing event in the same transaction, then let a separate publisher send the event after commit. If delivery succeeds but recording that success fails, the event can be sent again. Consumers must therefore handle duplicates idempotently."], ['What matters for retries?', "Use the driver’s transaction API and set an overall time budget. Follow its retry contract for TransientTransactionError (retry the transaction) and UnknownTransactionCommitResult (retry commit). The callback can run more than once, so keep external actions that cannot be safely repeated out of it."], ['Should cross-shard transactions be the default?', 'No. Reduce cross-shard dependencies first, then validate required atomicity, support, latency, conflict and recovery costs in the target deployment.']]),
'mongo/replica': card('Replica sets and write concern', 'Replica sets provide redundancy and elections; routing, concerns and sessions determine read visibility.', 'Explain topology, acknowledgement and retries as one end-to-end operation.',
'Read preference selects a destination; readConcern specifies reading guarantees, and writeConcern controls acknowledgement. Majority acknowledgement does not mean every replica immediately serves the write.\n\nTest elections, retries and read-after-write behavior. Replication also propagates mistakes, so maintain independent backups and tested restoration.',
['Read preference and readConcern solve different problems.', 'Replica sets are not backups.', 'Election recovery depends on network, configuration and member state.', 'Majority acknowledgement is not immediate visibility everywhere.'],
['Secondary reads may be stale.', 'Do not promise a universal election duration.', 'Replica counts cannot replace restore exercises.'],
[['What does w: majority guarantee?', 'It waits for configured majority acknowledgement conditions from voting data-bearing members, reducing failover loss risk. Durability also depends on journaling settings; not every replica has completed.'], ['How can clients read their own writes?', 'Sequence writes and reads within the same causally consistent session with majority writeConcern and majority readConcern. Primary preference alone does not replace these conditions; test failover and retries.'], ['How long do elections take?', 'There is no universal fixed duration. Timeouts, reachability, network and client discovery contribute; measure business recovery percentiles in exercises.'], ['What happens to transactions on failover?', "In-flight transactions can fail and commit outcomes can be uncertain. Follow the driver’s contract to distinguish transaction retries from commit retries, and make business operations on retried paths idempotent."], ['What should be monitored?', 'Member health, lag, oplog window, elections, connections, disk, business errors and tail latency. Validate recovery with failover and backup restoration.']]),
'mongo/schema': card('Modeling: embedding or references', 'Model documents around access and update boundaries, balancing consistency, growth and query cost.', 'Asset relationships and reports: explain embedding, references and precomputed views.',
'Embed bounded data that belongs to one aggregate and is accessed together; reference independently growing or shared entities where appropriate. Flexible schemas still need constraints.\n\nPlan migrations and redundant-field ownership. Precomputed results need provenance, version, freshness and reconciliation so derived data remains trustworthy.',
['Document boundaries should reflect aggregates and access patterns.', 'Bound arrays and document growth.', 'Assign responsibility for redundant-field updates.', 'Evolve validation and application compatibility together.'],
['Flexible structure does not remove constraints.', 'Do not embed unbounded history in one document.', 'Precomputation needs verification and rebuilding.'],
[['When does $lookup fit?', 'When indexed joins and data volumes are controlled. Inspect join cardinality, plans and memory; frequent complex joins may warrant another model or read view.'], ['How is the 16 MiB limit handled?', 'Split unbounded arrays and independent records, or use suitable large-object storage. Monitor growth and update cost before approaching the limit.'], ['How are schemas migrated safely?', 'Support old and new structures first, version data, backfill retryably and validate. Include concurrent new writes, then switch and remove legacy paths gradually.'], ['How does this compare with relational modeling?', 'Relational models emphasize normalization and joins; documents often organize aggregates. Both permit deliberate redundancy and require modeling against actual constraints.'], ['How are precomputed relationships trusted?', 'Record sources, versions and computation time. Combine incremental events with reconciliation, an explicit freshness budget, rebuilds and failure alerts.']]),
'mongo/mongo-shard': card('Sharded clusters', 'Shard keys and query patterns determine distribution, routing efficiency, hotspots and coordination cost.', 'Asset growth: distinguish deployed experience from candidate scaling designs.',
'Sharding distributes data; replication protects each shard’s availability. Choose keys using both stored-data and access distributions, not cardinality alone.\n\nMeasure fan-out and hotspots, verify uniqueness constraints and test migration capabilities against the deployed version. Adding shards does not repair every inefficient query.',
['High cardinality does not imply balanced load.', 'Hashing changes both write distribution and range-query targeting.', 'Unique indexes on sharded collections have shard-key constraints.', 'Migration capabilities are version-dependent.'],
['More shards are not a universal slow-query fix.', 'Large tenants and hot ranges require explicit handling.', '_id alone does not establish every cross-shard uniqueness guarantee.'],
[['What do mongos, config servers and shards do?', 'mongos routes queries, config servers hold cluster metadata, and shards store data. They have different capacity/reliability roles; mongos is not a data replica.'], ['How are hotspot keys identified?', 'Inspect frequency, monotonicity, read/write distribution and per-shard resources. Compare hashed/compound keys and dedicated large-tenant handling against actual queries.'], ['What does scatter-gather cost?', 'Multiple shards and result merging add network, CPU and tail latency. Target frequent queries with shard predicates and bound unavoidable fan-out.'], ['How do shards relate to replica sets?', "Each shard in a MongoDB sharded cluster is deployed as a replica set. Sharding distributes data and workload. Replication within a shard provides redundancy and failover. Plan the shard key, replica configuration and failure domains together."], ['How is global uniqueness enforced?', "A unique index on a range-sharded collection must have the shard key as its prefix. A hashed index cannot be unique. When _id is not the shard key, the default _id index enforces uniqueness per shard only. For global uniqueness, use a compatible shard key and index or assign IDs reliably in the application."]]),
'mongo/changestream': card('Change streams', 'Reliable change consumption needs resume tokens, retained history and idempotent effects.', 'CMDB incremental synchronization: define event meaning, recovery windows and rebuilding.',
'Change streams expose database changes, not automatically a business-event contract. Persist processing progress reliably and expect replay.\n\nMonitor lag against the available history window. Recovery after lost history needs a controlled snapshot/incremental handoff; resubscribing only from now can silently miss changes.',
['Resume tokens do not guarantee indefinite history.', 'Interpret fullDocument according to the requested options.', 'Keep consumption lag within retained history.', 'Rebuilds must join snapshots with concurrent changes.'],
['Saving progress before effects can skip work.', 'Change streams are not interchangeable with every message queue.', 'updateLookup is not necessarily the event-time document snapshot.'],
[['How do change streams differ from queues?', "Change streams reflect database changes and depend on the retained database history. Message brokers generally offer separate retention, consumption and routing. Business events need not map one-to-one to document changes. Choose based on decoupling and recovery needs."], ['What if a resume token is unusable?', 'Identify missing history or invalidation, stop outputs that depend on completeness, and rebuild or reconcile. Preserve the incremental handoff instead of silently starting from the present.'], ['Why still use an outbox?', "Write explicit business events in the same transaction as the business state to avoid inferring intent from field changes. A change stream can feed an outbox publisher, but it does not define the business event contract."], ['Is fullDocument exactly the event-time document?', 'Not necessarily. updateLookup can return a later majority-committed version. Exact pre/post images require appropriate version, configuration and retention.'], ['How do consumers become idempotent?', "Use a stable event ID or a business version to guard side effects, and persist processing state and checkpoints reliably. Reprocessing should yield the same business result. Each downstream consumer needs its own progress and recovery strategy."]]),
'redis/redis': card('Caching and protection', 'Redis needs explicit invalidation, memory and failure policies; availability does not establish business consistency.', 'Resource caches: explain failure paths, hotspot protection and verified benefit measures.',
'For cache-aside, read the authoritative store on a miss and invalidate after committed writes. Handle stale refills, failed deletion and multiple cache levels explicitly.\n\nBound memory, retries and source traffic. TTL contributes to freshness but is not a consistency protocol; critical decisions need an appropriate authoritative read/write design.',
['TTL alone is not a consistency protocol.', 'Match eviction to key purpose and expiry configuration.', 'Cache failures must not create unlimited database traffic.', 'Locks, caches and durable business data have different reliability needs.'],
['Redis availability is not data correctness.', 'Do not retry cache calls indefinitely.', 'Identical TTLs can cause synchronized source load.'],
[['What is cache-aside?', "On a cache miss, read from the authoritative store and populate the cache. After committing a write, invalidate the cached entry. Handle concurrent fills, invalidation failures and multiple cache layers. Use a stronger read and write protocol for critical decisions that require strict consistency."], ['Can Redis implement distributed locks?', 'It can provide conditional lease coordination with atomic acquisition, unique ownership and conditional release. Expiry, pauses and asynchronous failover affect exclusivity; critical writes need resource-side protection.'], ['How is eviction selected?', 'Match allkeys/volatile scope and LRU/LFU behavior to usage. Validate hits and eviction; noeviction can cause writes to fail at the limit.'], ['How are hot keys handled?', 'Identify read/write cost, then consider local caches, coalescing or business partitioning. More shards do not split one key; evaluate consistency and aggregation costs.'], ['What are negative-cache boundaries?', 'Cache confirmed absence briefly with bounded capacity and creation invalidation. Do not treat permission failures, timeouts and absence as equivalent.']]),
'redis/persist': card('AOF / RDB persistence', 'Persistence choices trade recovery paths and resource costs against acceptable data loss.', 'Set separate recovery objectives for disposable caches and persistent business state.',
'RDB snapshots and AOF logs offer different recovery characteristics. Match save/fsync policies to RPO, then measure write latency and background resource use.\n\nCopy consistent artifacts into an independent failure domain and test restoration. Replication, local persistence and backups protect different failures.',
['Replication and persistence protect different layers.', 'fsync affects durability, throughput and tail latency.', 'Rewrites can increase memory and disk pressure.', 'Restore tests must verify data and application operation.'],
['AOF does not guarantee zero loss in every failure.', 'Same-host files are not independent disaster recovery.', 'Backup creation alone does not prove restoration.'],
[['How should appendfsync be chosen?', "With appendfsync always, Redis calls fsync for each batch of writes, improving durability at a latency cost. everysec calls fsync once a second and can typically lose about one second of writes after a failure. no leaves flushing to the operating system. Choose based on acceptable data loss and tail latency."], ['How should Redis be backed up?', 'Capture consistent persistence artifacts, copy to another failure domain and control access, retention and checksums. Verify version-specific multipart AOF behavior before copying changing files.'], ['Why might data disappear after restart?', 'Check persistence settings, paths, last successful save/flush, corruption and logs. Also investigate expiry, eviction and application writes.'], ['Can RDB and AOF coexist?', "Yes. RDB provides point-in-time snapshots and AOF records writes. With both enabled, Redis reconstructs the dataset from AOF at startup because it is normally more complete. Keep independent backups and exercise recovery."], ['Does managed Redis remove this responsibility?', 'No. Verify backup cadence, granularity, failover and loss terms. The service reduces operations work but business owners must accept measured RPO/RTO.']]),
'redis/cluster': card('Cluster and Sentinel', 'Redis Cluster distributes keys across hash slots; single-key hotspots and cross-slot operations retain important limits.', 'Explain capacity limits, client support and the data-loss window around failures.',
'Choose sharding for a verified single-instance capacity or throughput limit. Smaller caches may suit replication with automatic failover without sharding complexity.\n\nCluster-aware clients must follow redirects and topology changes. Hash tags can colocate related keys, but cannot provide arbitrary cross-node transactions or eliminate failover loss.',
['Sharding cannot split one key’s execution load.', 'Clients must handle MOVED, ASK and topology changes.', 'Check slot restrictions for multi-key commands and scripts.', 'Majority reachability and durability are separate concerns.'],
['One hash tag for all keys defeats distribution.', 'Failover can lose acknowledged writes in some windows.', 'A proxy cannot hide every Cluster limitation.'],
[['When is Cluster needed?', 'When a measured capacity/throughput limit justifies sharding and the application accepts its constraints. Compare simpler primary-replica failover for smaller workloads.'], ['What do hash tags do?', 'Brace-delimited key content places related keys in one slot for supported multi-key operations. Bound each group to avoid concentrating data and traffic.'], ['What happens during a partition?', 'Topology and timeouts govern availability; some writes are rejected and some failure-window writes may be lost. Client success alone is not cross-failure strong consistency.'], ['Does a proxy remove cross-slot limits?', 'It may simplify routing, but cannot automatically create cross-node atomic transactions. Verify supported commands, errors, retries and failures beyond GET/SET.'], ['What matters during resharding?', 'Watch throughput, tail latency, network, memory and redirects. Migrate in bounded batches with recovery plans and representative load.']]),
'redis/hotkey': card('Hot keys and large keys', 'Hot keys concentrate request load; large keys add memory, transfer and operation costs. Diagnose them separately.', 'Resource hotspots: distinguish access concentration from object size using measurable outcomes.',
'Use bounded client sampling, latency and memory evidence to identify the costly keys. Diagnostic scans themselves must have controlled impact.\n\nLocal caching, coalescing and partitioning offer different consistency tradeoffs. Limit object size and request scope; additional nodes alone do not redistribute a single key.',
['Hotness and size can overlap or occur independently.', 'State sampling error and observation windows.', 'Partitioning changes consistency and aggregation.', 'Avoid unbounded scans and expensive production commands.'],
['Adding nodes alone does not move a single-key bottleneck.', 'Splitting keys adds merge costs.', 'UNLINK does not solve every large-object problem.'],
[['How are hotspots and large keys found?', 'Combine client sampling, command latency, memory analysis and bounded scans. Tool capabilities depend on version/policy; budget diagnostic cost.'], ['What consistency cost does splitting introduce?', 'Multi-key readers can observe mixed versions. Define versions, aggregation or accepted approximation; exact counters cannot simply scatter writes randomly.'], ['How do UNLINK and DEL differ?', "UNLINK removes keys from the keyspace immediately and can reclaim object memory in the background. DEL frees memory synchronously by default. The lazyfree-lazy-user-del enables asynchronous reclamation. Verify tail latency with representative object types, sizes and server settings."], ['Does Cluster solve one hot key?', 'Not automatically: the key belongs to one slot/node. Evaluate local caching, replica reads or business partitioning with explicit consistency limits.'], ['What protections belong in the application?', 'Rate-limit, bound fallback concurrency, coalesce requests and limit query/result size. Define degradation around downstream capacity and acceptable results.']]),
'redis/types': card('Data structures', 'Choose structures by operations, complexity and bounded size rather than storing everything as a large JSON value.', 'Explain cache models through concrete reads, writes and capacity limits.',
'Compare end-to-end reads and updates, including serialization, network and retention. Hashes help partial fields; strings simplify bounded whole-object replacement.\n\nLists, sets and sorted sets still need lifecycle limits. Single-command atomicity does not extend across multiple client round trips.',
['Compare end-to-end cost, not one command alone.', 'Bound collection sizes.', 'Encoding and memory depend on version, value size and element count.', 'Command atomicity does not cover multiple round trips.'],
['Avoid unbounded history in one hash.', 'A delayed-task index is not a complete reliable queue.', 'Sparse high bitmap offsets can waste memory.'],
[['Hash or String?', 'Consider Hash for frequent partial-field access and String for bounded whole-object replacement. Measure memory, network and updates rather than assuming one type is faster.'], ['How can Sorted Set schedule delayed tasks?', 'Use due time as score, but atomically claim/remove work and design acknowledgement, timeout redelivery and idempotency. Periodic scan/delete alone is unreliable.'], ['When is Bitmap unsuitable?', 'Very sparse IDs with huge offsets waste space, and multivalued attributes need another representation. Evaluate maximum offset, scans and retention.'], ['How are large hashes avoided?', "Split by business entity, time or bounded bucket, and define when fields are retired. Re-evaluate bulk reads, consistency and expiration after splitting. Native hash field expiration requires Redis 7.4 or later."], ['How are choices validated?', 'Use representative key counts, sizes and read/write mixes. Measure memory, throughput and tails, including expiry, deletion and recovery.']]),
'redis/distlock': card('Distributed locks', 'A lease coordinates ownership temporarily; protected resources must reject stale owners for critical writes.', 'Separate lock ownership, lease validity and resource-side write enforcement.',
'Acquire atomically with unique ownership and release only if that ownership still matches. Pauses and expiry can leave an old process executing after another obtains the lease.\n\nFor strict exclusion, use an appropriate coordination model and resource-side fencing or constraints. Renewal and cancellation cannot revoke side effects already in flight.',
['An owner ID is not a monotonic fencing token.', 'Renewal cannot revoke already-issued requests.', 'Resources must actually enforce stale-token rejection.', 'Asynchronous replication failover can break single-instance lock exclusivity.'],
['Never DEL without checking ownership atomically.', 'Client-only expiry checks cannot protect delayed writes.', 'Node voting alone cannot secure arbitrary external effects.'],
[['Why compare the owner when releasing?', 'An expired lock may belong to a new owner. Atomically compare and delete server-side; separate GET and DEL can remove the new lock.'], ['How should TTL be selected?', 'Use task-duration, pause and network distributions and cap execution time. Short TTLs increase expiry races; long TTLs delay recovery. No fixed TTL proves old work stopped.'], ['How does fencing work?', 'Each ownership grant gets a larger token. The resource atomically checks tokens with writes and rejects older ones. Unsupported downstream checks make the token ineffective.'], ['What follows renewal failure?', 'Stop new work and attempt cancellation, while resource-side checks prevent stale commits. Cancellation is cooperative; sending a signal does not prove effects ended.'], ['How should Redlock or voting be assessed?', 'State clock, delay, failure and durability assumptions against the invariant. Strict writes may require consensus, fencing or database constraints; node count alone is insufficient.']]),
'mq/mq': card('Reliable messaging', 'Separate message delivery from business processing; reliability requires idempotency, deliberate acknowledgements and recoverable state.', 'Identify failure windows across publishing, processing, acknowledgement and recovery.',
'A broker acknowledgement and a completed business operation are different events. Lost acknowledgements can cause successful operations to be retried; early acknowledgements can lose unfinished work.\n\nAssociate idempotency records with durable side effects, bound retries and retain enough history for recovery. Define exactly-once claims within an explicit transactional scope.',
['A lost acknowledgement can cause redelivery after successful processing.', 'Use bounded backoff and isolate persistent failures.', 'Coordinate idempotency records with the business side effect.', 'Retention and replay capacity are part of the recovery design.'],
['Acknowledging before durable processing can lose work.', 'A short-lived deduplication cache is not permanent idempotency.', 'A broker cannot make arbitrary external side effects exactly once.'],
[['What does exactly once cover?', "In a Kafka-to-Kafka read-process-write pipeline, commit output records and consumed offsets in the same producer transaction, and use read_committed downstream. External systems must participate in coordination or provide a mechanism such as transactional deduplication or idempotent writes for the business outcome."], ['What do transactional messages solve?', "They coordinate the producer’s local transaction outcome with message eligibility for delivery, reducing the risk of a committed business change without its event. Consumer work has its own transaction boundary and still requires idempotency."], ['How are poison messages handled?', 'Bound retries and isolate failures with their operation IDs and diagnostic context. Replay under control; do not block an ordered group indefinitely without an explicit recovery policy.'], ['How is an idempotency key chosen?', 'Use a stable business operation ID with a defined scope and payload validation. Reuse it on retries, separate distinct operations and retain records across the redelivery window.'], ['Are delayed messages precise timers?', 'No. Delivery eligibility is not a real-time execution guarantee. Check current business state, duplicates and lateness; reconcile critical deadlines independently.']]),
'mq/backlog': card('Backlog management', 'Backlogs indicate a gap between arrival and completion rates; identify the constraint before scaling.', 'Explain message age, completion throughput and the estimated recovery time.',
'Observe the oldest message and successful completion rate, not only queue depth or read rate. Locate skew, expensive handlers, retries and downstream saturation.\n\nIncrease concurrency only within partition and downstream limits. Admission control and controlled replay keep recovery traffic from creating another overload.',
['Message age expresses user impact better than depth alone.', 'Partitioning can limit useful consumer parallelism.', 'Retries consume capacity and belong in load estimates.', 'Scale within downstream connection and throughput budgets.'],
['Adding consumers does not always increase throughput.', 'Average processing time can hide slow partitions.', 'Unbounded replay can overload recovering services.'],
[["Does adding consumers beyond the partition count improve throughput?", "With partition assignment in one consumer group, adding instances beyond the number of assignable partitions generally adds no processing parallelism. Check the broker model, hot partitions and per-message processing cost."], ['When should service be degraded?', 'Act before latency or capacity budgets are exhausted. Specify which low-priority operations may be delayed, merged or dropped; clearing a queue is not a general recovery strategy.'], ['How much backlog is acceptable?', "Derive limits from maximum acceptable message age, arrival rate and available recovery capacity. Define freshness targets and alert thresholds separately for workloads such as payments, audit and reporting."], ['Which metrics matter?', 'Track depth, oldest age, arrival and completion rates, retries, failures, processing latency, partition skew and downstream health. Reading a message is not successful processing.'], ['Can HPA use consumer lag?', "Expose consumer lag to the HPA as a custom or external metric through a metrics adapter. Set a replica cap and scaling stabilization windows, accounting for partition parallelism and downstream capacity to limit rebalance churn, connection contention and retries."]]),
'mq/ordering': card('Partition keys and ordering', 'Ordering is usually scoped to a partition or message group; consumer concurrency and state updates determine the final result.', 'Explain aggregate keys, operation versions and recovery from out-of-order events.',
'Choose the business aggregate whose updates must be ordered, then map it to a stable partition or group. A globally ordered stream reduces opportunities for parallelism.\n\nBroker order does not guarantee effect completion order. Atomically validate versions or state transitions when applying events, and define how missing, duplicate or failed events are reconciled.',
['Global ordering constrains concurrency and availability.', 'Send order, log order and side-effect completion order differ.', 'Skipping a failed event can break state continuity.', 'Version checks must be atomic with the protected update.'],
['Asynchronous handlers can reorder effects within one partition.', 'Client timestamps are not necessarily authoritative versions.', 'Transactional messaging does not automatically provide ordering.'],
[['How are out-of-order events handled?', 'Use versions or a state machine: ignore or record obsolete events, and wait or reconcile when required predecessors are missing. Apply the check and state update atomically.'], ['How is a partition key chosen?', "Use the ID of the business aggregate that needs ordering, such as an order ID. A key that is too coarse can create hotspots, while a key that is too fine can split events that must stay ordered. Verify compatibility between old and new messages when changing the key or partition count."], ["Can multiple downstream systems share one ordering guarantee?", "Each consumer group or downstream system has independent progress and concurrency. Log order does not make changes take effect simultaneously across systems. Apply version checks in each system and observe state across systems."], ['How do ordering and transactions relate?', 'Producer transaction coordination and scoped message order solve different problems. Verify whether the required combination is supported by the broker and client version.'], ['How is ordering tested?', 'Inject duplicates, delays, retries, restarts and rebalances. Assert business invariants, including that an older event cannot overwrite newer state.']]),
'mq/choice': card('Choosing a message broker', 'Compare reliability, ordering, replay, latency and operational requirements before peak throughput.', 'State workload constraints and measured evidence rather than a universal product ranking.',
'Define the workload and failure contract first. A task queue, replayable event log and delayed workflow may need different capabilities.\n\nCompare equivalent durability, acknowledgement and replication settings. Include tail latency, recovery behavior, consumer effects and the team’s operational experience in the decision.',
['Throughput comparisons require equivalent hardware and durability settings.', 'Capabilities depend on broker and client versions.', 'Replay must handle older schemas and repeated side effects.', 'Operational maturity is part of the selection criteria.'],
['Vendor peak throughput is not application throughput.', 'A product-level guarantee may not cover the full business operation.', 'Multiple brokers need a concrete benefit that justifies maintenance.'],
[['How should ordering be compared?', 'Compare ordering scope, producer retries, consumer parallelism, failure blocking and recovery. A single “ordered” label hides meaningful differences.'], ['Is at-least-once delivery unconditional?', 'No. Protocol, persistence, acknowledgement, retry and retention settings matter. Premature application acknowledgements can still lose unfinished work.'], ['How should brokers be benchmarked?', "Use equivalent message sizes, batching, replication and acknowledgement settings. Measure throughput, P99 latency, resource use and failure recovery, including real consumer logic and downstream writes."], ['When are multiple brokers justified?', 'When conflicting workload requirements justify the added expertise, monitoring, upgrades and incident burden. Prefer fewer systems when one meets the constraints.'], ['What can go wrong during replay?', 'Older schemas, duplicate effects and downstream overload. Use compatible decoding, explicit idempotency scope, rate limits and auditable replay boundaries.']]),
'mq/txmsg': card('Delayed and transactional messages', 'RocketMQ transactional messages coordinate local producer transactions through half messages, commit or rollback, and transaction checks.', 'Explain durable transaction evidence, timeout handling and consumer responsibilities.',
'A half message is stored but not yet available to consumers. After the local transaction, the producer reports commit or rollback; uncertain outcomes may trigger broker checks.\n\nChecks must read durable state tied to the specific operation. Bound uncertainty and reconcile exceptions. This coordination neither creates a cross-service database transaction nor removes consumer idempotency requirements.',
['Transaction checks need durable evidence associated with the message operation.', 'Unknown is a distinct state, not an automatic rollback.', 'Transaction checks have version-dependent time and retry limits.', 'Consumers still need idempotent processing.'],
['Record existence alone may not prove the intended operation committed.', 'Transactional messages are not a distributed database transaction.', 'Reconcile transactions that remain unpublished or unresolved after timeouts.'],
[['What is a half message?', 'A message retained by the broker but withheld from consumers pending the producer’s transaction outcome. Confirm the lifecycle and limits for the deployed version.'], ['What should a transaction check query?', "Query a durable local transaction outcome tied to the operation. Distinguish commit, rollback and unknown. The record must reliably correspond to the business state. A cache flag or process-local Boolean is insufficient."], ['Can transactional messages also be delayed or ordered?', 'These are separate capabilities. Check the product, version and client constraints for the required combination rather than assuming compatibility.'], ['How does this compare with an outbox?', 'An outbox commits business data and an event locally, then publishes it. Transactional messaging uses broker coordination and checks. Both need duplicate handling, failure recovery and reconciliation.'], ['Why must the consumer still be idempotent?', 'A consumer can finish processing and lose its acknowledgement, causing redelivery. Producer-side transaction coordination does not cover consumer-side external effects.']]),
'container/arch': card('Kubernetes architecture', 'Kubernetes reconciles desired state through APIs and control loops; scheduling, execution and networking have separate responsibilities.', 'Trace one resource creation and one recovery sequence through the components.',
'The API records desired state. Controllers reconcile resources, the scheduler assigns Pods to nodes, and kubelets use the container runtime to start containers. Networking and storage depend on the installed implementations.\n\nThese steps are asynchronous. Diagnose state transitions and events at each boundary; a highly available control plane alone does not guarantee application availability.',
['Controllers continuously reconcile state.', 'The scheduler selects nodes; it does not start containers.', 'etcd stores cluster state and needs independent backup and recovery.', 'Networking and storage rely on plugins and node components.'],
['Do not assign every responsibility to the kubelet.', 'Control-plane availability is not application availability.'],
[['What happens after creating a Deployment?', 'The Deployment controller manages ReplicaSets, which maintain Pod counts. The scheduler binds Pods to nodes; kubelets then drive container startup. Observe each asynchronous step through status and events.'], ['Who creates Pods?', 'Typically workload controllers such as ReplicaSet, Job or StatefulSet controllers use the API. Users can create Pods directly, but that does not provide equivalent controller-managed recovery.'], ['What happens if etcd fails?', 'Control-plane reads and writes may be blocked, affecting creation, scheduling and reconciliation. Existing containers may continue running. Recovery must protect cluster-state consistency.'], ['What does kube-proxy do?', 'It implements node-level Service forwarding according to the configured mode. Some networking implementations replace it; it does not generally allocate Pod addresses.'], ['What does control-plane HA require?', 'Redundant API access and control components, reliable etcd quorum, failure-domain planning, certificates and tested backup/recovery. Test both management and workload behavior after member loss.']]),
'container/workload': card('Pods and workload controllers', 'Choose controllers according to replica, identity and completion semantics, together with the application’s state model.', 'Separate orchestration guarantees from application-level state recovery.',
'Deployments manage replaceable application replicas. StatefulSets provide stable identities and storage associations, DaemonSets cover eligible nodes, and Jobs represent finite work.\n\nControllers replace failed instances but cannot infer business correctness. Stateful replication remains an application concern, and retried or scheduled jobs require idempotency and result validation.',
['Pods are replaceable; avoid dependence on temporary instance identity.', 'StatefulSet does not implement database HA by itself.', 'Job retries can repeat side effects.', 'CronJobs need explicit time-zone, concurrency and missed-schedule policies.'],
['Scheduled jobs are not guaranteed to execute exactly once.', 'Stable StatefulSet names do not prove data safety.'],
[['When is Deployment unsuitable?', 'Consider StatefulSet for stable identity or dedicated persistent volumes, DaemonSet for node agents, and Job for finite work. Choose lifecycle semantics rather than language or image names.'], ['How do ReplicaSet and Deployment relate?', 'ReplicaSet maintains a Pod count; Deployment manages ReplicaSet revisions and rolling updates. Usually manage stateless applications through Deployment without independently changing its children.'], ['What does StatefulSet provide?', 'Stable network identity, ordinals and volume claims, with policy-dependent startup/update ordering. Database replication, leadership and data recovery remain application or operator responsibilities.'], ['When should DaemonSet be used?', 'For node-level logging, networking or monitoring agents. Configure node selection, tolerations and resource limits so agents do not compromise application workloads.'], ['How are failed Jobs handled?', 'Inspect exit codes, backoff limits, deadlines and failure policies. Use idempotency or checkpoints, and validate external results; a successful process exit alone may be insufficient.']]),
'container/cni': card('Pod networking / CNI', 'Pod connectivity, Service forwarding and network policies are separate layers; verify addressing, routing and access rules independently.', 'Trace the request path instead of using component restarts as a diagnosis.',
'CNI defines an interface used by networking implementations. The actual Pod path may use direct routes, tunnels or other mechanisms; Service routing and policy enforcement have their own responsibilities.\n\nCheck endpoints and application readiness before changing the data plane. Confirm the deployed plugin and Kubernetes version rather than assuming a universal forwarding mode.',
['CNI is an interface and ecosystem, not one network implementation.', 'Service forwarding depends on cluster configuration.', 'NetworkPolicy requires an implementation that enforces it.', 'Working Pod-to-Pod traffic does not prove Service or DNS health.'],
['Not every cluster uses the same kube-proxy mode.', 'Inspect backend availability before changing network rules.'],
[['How does traffic reach another Pod?', 'The network implementation supplies reachability through routes, tunnels or other forwarding. Inspect plugin configuration, node placement and MTU; direct Pod traffic need not pass through a Service.'], ["How do the iptables and IPVS modes of kube-proxy differ?", "The iptables mode uses rules to select and redirect traffic to Service backends. IPVS uses the kernel IPVS and iptables APIs. IPVS mode was deprecated in Kubernetes 1.35. Assess nftables or iptables against the cluster version, node kernel and network plugin before migrating."], ['Does installing CNI enable NetworkPolicy?', 'Only if the implementation supports and enforces it. Validate selectors, namespaces, directions and ports with actual allowed and denied connection tests.'], ["What if a Service has no ready backends?", "Check the selector, Pod labels, readiness, port mappings and EndpointSlices. If there are no ready endpoints, diagnose the objects and application before changing the data plane."], ['How do kube-proxy and CNI differ?', 'CNI commonly handles Pod network attachment; kube-proxy handles Service forwarding. Some implementations integrate or replace the latter. Verify the actual deployment.']]),
'container/volume': card('PV / PVC / StorageClass', 'PVCs request storage and PVs represent bindable resources; access modes, topology and reclaim policies determine behavior.', 'Explain access constraints, deletion semantics and data-recovery ownership.',
'A claim must match capacity, access and topology requirements. Dynamic provisioning creates storage through a StorageClass; static provisioning binds administrator-created volumes.\n\nCoordinate placement with volume accessibility. Before deleting claims or restoring snapshots, verify reclaim behavior, application consistency and the backup failure domain.',
['Access modes do not replace filesystem permissions.', 'WaitForFirstConsumer coordinates binding with scheduling topology.', 'Reclaim policy governs storage handling after claim deletion.', 'Define separate failure domains for snapshots and backups.'],
['ReadWriteOnce generally means one node, not one Pod.', 'Check reclaim policy before deleting a PVC.'],
[['How is a Pending PVC diagnosed?', 'Inspect claim events, StorageClass, provisioner, capacity and access modes, then consumer scheduling and topology. Identify the blocking condition before deleting and recreating resources.'], ['How do RWO, RWX and RWOP differ?', "ReadWriteOnce (RWO) allows a read-write mount from a single node, potentially shared by Pods on that node. ReadWriteMany (RWX) allows read-write mounts from multiple nodes. ReadWriteOncePod (RWOP) restricts mounting to a single Pod across the cluster and requires a compatible CSI volume and Kubernetes version."], ['What is static versus dynamic provisioning?', 'Administrators create static PVs in advance. Dynamic provisioners create backing storage from claims and StorageClasses. Both must satisfy capacity, access and topology requirements.'], ['What does Released mean?', 'The previous claim was released but reclamation or reuse is incomplete. Check policy, retention requirements and claimRef; do not assume rebinding is safe.'], ['Why does binding affect scheduling?', 'Volumes may be accessible only in specific zones or nodes. Early binding can constrain placement; WaitForFirstConsumer coordinates topology with scheduling, subject to resource and provisioner availability.']]),
'container/rbac': card('RBAC and ServiceAccounts', 'RBAC authorizes subjects to perform operations on resources; design least privilege around actual namespace and API needs.', 'Use concrete deployment API calls to explain permissions and audit evidence.',
'Identify the subject, resource, subresource, verb and scope before writing roles. RoleBindings can reuse ClusterRoles while limiting applicable permissions to a namespace.\n\nReview indirect access too: permission to create a Pod can expose Secrets it mounts. Keep workload credentials short-lived and avoid granting broad administration merely to simplify deployment.',
['RBAC permissions are additive; there are no explicit deny rules.', 'Namespaced grants do not authorize cluster-scoped resources.', 'ServiceAccounts identify workloads.', 'Review both direct Secret reads and workloads that can mount Secrets.'],
['Do not give CI cluster-admin by default.', 'A namespace alone is not a complete security boundary.'],
[['Can a RoleBinding reference a ClusterRole?', 'Yes. It reuses rules for applicable resources within the binding’s namespace. It does not grant cluster-wide access; that requires an appropriately scoped binding.'], ['What permissions does deployment need?', "Grant only the required verbs, such as get, create or patch, on the relevant resources and namespaces. Avoid unnecessary Secret reads, arbitrary access to pods/exec and RBAC modifications."], ['How do users and ServiceAccounts differ?', 'User identities usually come from external authentication; ServiceAccounts are Kubernetes-managed namespaced workload identities. Configure token lifetimes and mounting for the deployed version.'], ['Why is Secret access sensitive?', 'It can expose database and external-service credentials. Creating workloads that mount Secrets may provide indirect access, so audit both capabilities.'], ['How is a 403 diagnosed?', 'Confirm the actual identity, namespace, resource, subresource and verb, then inspect bindings and rules with tools such as auth can-i. Do not bypass diagnosis with administrator privileges.']]),
'container/isol': card('Container isolation / cgroups', 'Containers combine kernel isolation and resource controls; the security boundary depends on privileges, the host and runtime configuration.', 'Explain concrete security, resource and performance trade-offs in the runtime baseline.',
'Containers share a kernel while isolating process views and controlling resources. CPU limits can throttle execution; memory limits can lead to OOM termination.\n\nUse minimal privileges, appropriate users and restricted host access. Combine vulnerability scanning with provenance, patching and runtime controls, and measure latency as well as resource usage.',
['CPU limits can cause throttling; memory pressure can trigger OOM.', 'Non-root does not imply the absence of other privileges.', 'Image scanning covers only detectable problems.', 'Containers do not each have an independent VM kernel.'],
['A privileged container does not provide an ordinary isolation boundary.', 'CPU utilization alone can hide throttling and latency.'],
[['Can image scanning guarantee security?', 'No. It detects known vulnerabilities and some configuration problems, not all application or runtime risks. Also control provenance, signature verification, privileges, networking and patching.'], ['How do requests and limits differ?', 'Requests influence scheduling and allocation; limits constrain runtime use. CPU is generally throttled and memory excess can cause OOM. Validate behavior for the workload and platform version.'], ['Why can a throttled Pod remain Ready?', 'Readiness reflects the configured probe, not necessarily an SLO. Observe throttling, queues and tail latency alongside probes.'], ['What risk comes from a shared kernel?', 'Kernel vulnerabilities or excessive privileges can weaken isolation. Evaluate stronger isolation for high-risk tenancy and restrict host paths, devices and privileged execution.'], ['What is needed for non-root execution?', 'Set UID/GID, file and volume permissions, remove unnecessary capabilities and verify privileged ports or system writes are unnecessary. Changing image USER alone is insufficient.']]),
'container/docker': card('Container image fundamentals', 'Build traceable runtime artifacts with explicit dependencies and controlled privileges; a successful build is one delivery step.', 'Connect the image digest, build record and runtime validation.',
'Multi-stage builds separate build tools from runtime dependencies. Exclude credentials and unrelated files from the build context, and identify releases by immutable content.\n\nValidate libraries, certificates, permissions and startup behavior in the final image. Cache reuse improves build speed but does not replace testing, scanning or provenance.',
['Tags can change; digests identify specific image content.', 'Exclude credentials and irrelevant files from the build context.', 'Build caching does not replace traceability.', 'Test and scan the final artifact.'],
['Do not store secrets in ARG, ENV or image layers.', 'Do not use latest as the only release identifier.'],
[['Why use multi-stage builds?', 'Copy only runtime artifacts into the final image, excluding compilers and intermediates. Still verify dynamic libraries, certificates and permissions; excessive trimming can break execution.'], ['Why not rely on latest?', 'A tag can point to different content over time. Record immutable digests or controlled version tags and connect deployment records to their builds.'], ['How is a non-root image built?', 'Create a restricted user, set file permissions and validate unprivileged ports and filesystem requirements. Runtime capability and privilege-escalation restrictions remain necessary.'], ['How can cache hit rates improve?', 'Copy stable dependency manifests before application code and use appropriate cache mounts. Keys must include relevant inputs, dependency compatibility and target platform.'], ['Docker or Podman?', 'Compare daemon models, rootless execution, build compatibility and team tooling. OCI compatibility does not make every network, cache or CLI behavior identical; test the actual delivery workflow.']]),
'container/probe': card('Probes and rolling updates', 'Readiness controls ready backend eligibility, liveness triggers restarts, and startup probes provide a separate initialization budget.', 'Validate releases with observed traffic outcomes, not configuration alone.',
'Use probes for distinct questions: has startup finished, can this instance serve traffic, and should this container be restarted? Set budgets around measured behavior.\n\nCoordinate replicas, rollout parameters, spare capacity and graceful shutdown. Test in-flight requests and long-lived connections; evaluate release-window errors and latency before claiming interruption-free delivery.',
['Startup probes can delay liveness and readiness until startup succeeds.', 'Readiness alone does not prove SLO compliance.', 'Rollout settings and PodDisruptionBudgets have different scopes.', 'Termination must account for in-flight requests and long-lived connections.'],
['One trivial check may not suit all probe responsibilities.', 'Probes and PDBs alone cannot guarantee zero downtime.'],
[['How can disruption during releases be minimized?', "Combine sufficient ready replicas, rolling-update settings, spare capacity, readiness checks and graceful termination. Test connection draining and long requests, then verify release-window error rates and latency."], ['When is startupProbe appropriate?', 'For slow or variable startup, provide a separate budget to avoid premature liveness restarts. Normal readiness and liveness checks begin after startup succeeds.'], ['How do probes relate to HPA?', 'Probes affect instance state; HPA changes replica counts from configured metrics. Scaling latency, startup time and metric delays require joint validation.'], ['How should a failed release be rolled back?', 'Use errors, latency and health to trigger controlled rollback, checking configuration and data compatibility. Reverting an image does not reverse database migrations or external effects.'], ['What does an exec probe cost?', 'It runs a process inside the container. Frequent checks consume resources; choose inexpensive checks and suitable periods, timeouts and thresholds.']]),
'container/sched': card('Scheduling and resources', 'The scheduler places Pods using resource requests and constraints; runtime contention also needs limits, priorities and capacity planning.', 'Explain measured baselines, placement constraints and peak capacity.',
'Requests express scheduling needs; limits constrain runtime use. Measure representative workloads and startup peaks rather than treating low average utilization as spare guaranteed capacity.\n\nCombine affinity, taints and priorities deliberately. Autoscaling still requires eligible node resources and downstream capacity, while overcommit must account for correlated peaks.',
['Scheduling primarily uses declared requests, not instantaneous idle capacity.', 'Tolerations permit placement but do not force node selection.', 'Priority and QoS are different concepts.', 'Scaling requires eligible nodes and dependency capacity.'],
['Limits are not scheduling reservations.', 'Guaranteed QoS does not make a Pod immune to termination.'],
[['What does QoS influence?', "Resource declarations determine a Pod’s QoS class. For node-pressure eviction, kubelet considers whether usage exceeds requests, Pod priority and usage relative to requests. QoS class alone does not determine the eviction order."], ['How should requests be sized?', 'Measure representative load, startup peaks and performance goals, then refine. Low values encourage contention; excessive values waste capacity and increase Pending risk.'], ['How do taints and tolerations interact?', 'Taints restrict Pods without suitable tolerations. A toleration permits placement but does not select the node; use affinity or other constraints for dedicated placement.'], ['What are overcommit risks?', 'Concurrent peaks can cause throttling, OOM or eviction. Base overcommit on workload correlation, priorities and failure budgets rather than utilization alone.'], ['Can VPA and HPA coexist?', 'Yes, with deliberate separation of metrics and responsibilities. Simultaneous CPU or memory adjustments can interact; verify update modes, Pod recreation and platform support.']]),
'container/cicdlink': card('Connecting CI to deployment', 'CI validates changes and produces traceable artifacts; CD applies validated versions and checks runtime outcomes.', 'Explain artifact promotion, permissions and operational acceptance.',
'Build an artifact once, record its identity, and promote that artifact through controlled environments. Separate build credentials from deployment identities.\n\nApply environment configuration, serialize conflicting releases and verify both rollout health and business behavior. A successful deployment command is not complete acceptance.',
['Separate build and deployment credentials.', 'Represent environment differences through controlled configuration.', 'Serialize releases to prevent older pipelines overwriting newer versions.', 'Deployment success is not business acceptance.'],
['A successful kubectl exit code does not complete release validation.', 'Ordinary build jobs should not hold production administrator credentials.'],
[['How should CI and CD be divided?', 'CI validates changes and produces reusable artifacts; CD manages environment changes, release strategy and runtime acceptance. Teams may choose different boundaries, but provenance and ownership must remain explicit.'], ['How is drift handled?', 'Compare desired and actual state, distinguish legitimate emergency changes from unwanted modifications, then reconcile deliberately. Blind periodic overwrite can discard a valid repair.'], ['What does Helm provide?', 'Templating and release management for Kubernetes resources. Review rendered manifests, dependencies, values and migrations; record chart and image versions. Helm does not validate business correctness.'], ['When is canary deployment useful?', 'When traffic can be allocated, metrics distinguished by version, and data remains compatible. Low traffic or long jobs may require synthetic validation and longer observation.'], ['How are deployment permissions constrained?', 'Use environment-specific identities and least-privilege RBAC, restricted namespaces and resources, and protected release entry points. Audit actor, pipeline, version and outcome together.']]),
'container/config': card('ConfigMaps and Secrets', 'Manage configuration and credentials separately; update behavior depends on injection and application reload support.', 'Show validation, version changes and evidence that new configuration took effect.',
'Configuration needs a version, validation and observable activation. Environment variables require process replacement; projected files need application rereads and have propagation constraints.\n\nSecrets additionally require protected storage, transmission and access. Plan rotation and revocation; encoding a value does not encrypt it.',
['Version, validate and observe configuration activation.', 'Protect Secrets at rest, in transit and at the consuming application.', 'Reload behavior depends on both injection and application support.', 'Keep sensitive values out of logs, images and ordinary configuration repositories.'],
['Base64 is not encryption.', 'Updating a ConfigMap does not immediately change process environments.'],
[['Do ConfigMap changes apply automatically?', "Recreate Pods to pick up ConfigMap changes injected as environment variables. Regular volume projections eventually update, and the application must reread the files. Files mounted through subPath do not receive updates. Verify the actual injection method."], ['What does external secret management add?', 'Centralized lifecycle management and auditing with controlled synchronization or mounting. Evaluate propagation delays, availability dependencies, rotation and compromise response.'], ['How should Nacos and ConfigMap coexist?', 'ConfigMaps integrate with cluster resource delivery; Nacos supplies application configuration and discovery. Avoid competing authorities and define versions, release ownership and failure fallback.'], ['Why use immutable configuration?', 'It prevents in-place content changes and supports explicit versioned names. Plan reference changes, retention and cleanup, especially for sensitive old versions.'], ['What happens after credential exposure?', 'Revoke or rotate credentials, verify dependent systems switched, and investigate access history and exposure scope. Deleting the string from a repository does not invalidate leaked credentials.']]),
'container/svc': card('Services and ingress', 'Services provide stable discovery and access; Ingress or Gateway API describes supported ingress routing implemented by controllers.', 'Separate discovery, routing, TLS and application authorization.',
'A Service selects or references backends and exposes access according to its type. Ingress and Gateway API require implementations that support the desired protocols and routing policies.\n\nCheck ports, endpoints, health and controller behavior. Traffic distribution and certificate handling require explicit validation rather than assumptions from resource declarations.',
['Resource declarations require a corresponding controller or platform implementation.', 'Service ports must match application listeners.', 'Discovery does not replace health or authorization.', 'Ingress and Gateway API capabilities vary by implementation.'],
['LoadBalancer does not automatically obtain an external address in every environment.', 'Replica proportions do not guarantee exact traffic weights.'],
[['When is a headless Service useful?', 'When clients need individual backend addresses, such as stateful services with stable identities. Clients must handle multiple addresses; there is no ordinary ClusterIP virtual-address forwarding.'], ['Gateway API versus Ingress?', 'Gateway API offers a richer resource and responsibility model; Ingress mainly describes HTTP/HTTPS entry. Verify routes, extensions and migration costs with the selected controller.'], ['How is canary traffic controlled?', 'Use supported weights, request attributes or user cohorts and observe metrics by version. Connection reuse and balancing can make traffic differ from replica ratios.'], ['How is a Service reached across namespaces?', 'Use its namespace-qualified DNS name, subject to network policies and application authorization. Resolution alone does not prove connectivity or permission.'], ['What are ExternalName limitations?', 'It supplies a DNS alias rather than proxying traffic. It does not resolve certificate or HTTP Host mismatches; client behavior and TLS validation must fit the target.']]),
'container/netpol': card('NetworkPolicy', 'NetworkPolicy constrains Pod reachability through additive directional rules, enforced by a supporting network implementation.', 'Demonstrate tenant isolation with explicit allowed paths and connection tests.',
'Select the relevant Pods and namespaces, then define ingress and egress permissions. Policies in the same direction combine their allowed traffic.\n\nMap dependencies before introducing isolation, including DNS and telemetry. Verify both permitted and denied connections; policy objects alone do not prove enforcement or complete tenant isolation.',
['Policies select Pods using conditions such as Pod and namespace labels.', 'Allowed traffic is the union of applicable rules in a direction.', 'Default isolation can affect DNS and monitoring.', 'Test both allowed and denied connections.'],
['Standard NetworkPolicy is not a layer-7 identity policy.', 'Do not isolate production broadly before mapping dependencies.'],
[['How is enforcement verified?', 'Check plugin support and the selected endpoints, then test allowed and blocked paths. Successful creation of a policy object does not prove data-plane enforcement.'], ['How does a service mesh differ?', 'NetworkPolicy primarily governs reachability. A mesh may add workload identity, mTLS and layer-7 authorization. Combine them according to the threat model.'], ['How are policy-related failures diagnosed?', "Check source and destination labels, namespace selectors, ports and DNS dependencies. If both ends are isolated, source Pod egress and destination Pod ingress must both allow the connection. Then inspect NAT and plugin behavior using narrowly scoped tests."], ['Why are egress rules easy to miss?', 'Applications also need DNS, databases, telemetry and external APIs, sometimes at changing addresses. Inventory and validate these dependencies rather than allowing only the main application port.'], ['Does this fully isolate tenants?', 'No. It covers part of the network boundary. RBAC, quotas, storage controls, application authorization and potentially stronger compute isolation are also needed.']]),
'container/etcd': card('Operating etcd', 'etcd maintains coordination state through consensus; protect quorum, disk latency, capacity and recoverability.', 'Explain majority availability, recovery evidence and safe operation ordering.',
'Preserve quorum when changing members or performing maintenance. Disk and network latency affect committed writes and control-plane behavior; adding members is not a write-throughput scaling technique.\n\nManage retained history and physical fragmentation separately. Store verified snapshots independently and rehearse recovery with version-compatible procedures.',
['An odd number of voting members supports sensible fault-tolerance sizing.', 'History compaction and physical defragmentation are different operations.', 'Snapshots need independent storage, validation and restore exercises.', 'Recovery procedures must match etcd and Kubernetes versions.'],
['Adding members is not a general way to scale write throughput.', 'Do not restart all members while their state is unknown.'],
[['How often should backups run?', 'Choose from acceptable state-loss windows, change frequency and recovery cost, with extra backups before risky changes. Verify readability and restoration rather than counting files.'], ['Which performance metrics matter?', 'Disk fsync and commit latency, leader changes, network health and database size, correlated with API-server latency. Avoid shared-storage contention and excessive state churn.'], ['Why not operate it like MongoDB?', 'The data model and consistency protocol differ. etcd serves coordination state rather than general large business datasets; membership, backup and scaling must respect consensus requirements.'], ['How are space alarms handled?', 'Identify why writes are restricted, then follow documented compaction, defragmentation and alarm-clearing steps. Fix abnormal growth; increasing quota alone may postpone recurrence.'], ['What should certificate rotation validate?', 'Trust chains, member/client identities, validity and reload behavior. Rotate in quorum-preserving steps, verify peer and API access, and retain a controlled fallback.']]),
'container/troubleshoot': card('Kubernetes troubleshooting', 'Start with the business symptom and narrow the fault using state, events, logs and metrics.', 'Present symptoms, evidence, recovery actions and measures that prevent recurrence.',
'Build a timeline of symptoms and changes. Inspect resource state and events, including previous container logs, before destructive recovery removes evidence.\n\nSeparate the displayed status from the cause: restart backoff, readiness and Pending each have multiple explanations. Test falsifiable hypotheses and record mitigation separately from permanent repair.',
['Preserve previous-container logs as well as current logs.', 'Correlate events and metrics over the same time window.', 'Distinguish exit codes, OOM indicators and probe failures.', 'Record mitigation separately from root-cause repair.'],
['Deleting Pods first can destroy diagnostic evidence.', 'Pending and restarts do not always mean insufficient resources.'],
[['How is CrashLoopBackOff diagnosed?', 'Inspect previous logs, exit reasons, startup commands, configuration and probes. The status describes backoff after repeated exits; identify application failure, OOM or liveness-triggered restart.'], ['Why high latency with low CPU?', 'Check throttling, queues, lock contention, downstream waits and sampling resolution. Average utilization can hide bursts or a single-thread bottleneck.'], ['How is PVC Pending diagnosed?', 'Use events to distinguish provisioning, capacity, access-mode, topology and consumer-wait conditions. Inspect storage and scheduling before deleting claims with important data references.'], ['How should monitoring guide diagnosis?', 'Correlate errors, latency, saturation and changes, then test falsifiable hypotheses. Missing telemetry is unknown, not proof of health.'], ['How is a noisy neighbor identified?', 'Compare colocated workloads and CPU, memory, disk and network pressure. Validate shared-resource contention through controlled movement or limits before redesigning isolation.']]),
'container/node': card('Node maintenance / drain', 'Limit unavailable capacity during maintenance using cordon, controlled eviction and recovery checks.', 'Record capacity checks, evictions and application recovery outcomes.',
'Cordon prevents ordinary new scheduling; drain handles existing movable workloads subject to eviction constraints. Check spare capacity, healthy replicas and failure domains before beginning.\n\nRespect disruption budgets and special workloads, and explicitly protect local data. Complete maintenance only after applications recover, not merely when the node reports Ready.',
['Eviction API behavior can respect PDBs; direct deletion differs.', 'DaemonSet and static Pods need special handling.', 'Local temporary data may be lost during migration.', 'Batch size depends on failure domains and remaining capacity.'],
['Do not bypass every protection merely to make drain succeed.', 'Node Ready alone does not complete business validation.'],
[['How do cordon and drain differ?', 'Cordon marks a node unschedulable; existing Pods stay. Drain additionally evicts or handles eligible workloads, with special cases for particular Pod types.'], ['What if drain is blocked?', 'Inspect PDBs, replica health, unmanaged Pods, local data and eviction events. Restore capacity first; understand business consequences before bypassing protections.'], ['What happens to DaemonSets?', "When DaemonSet Pods are present, kubectl drain requires --ignore-daemonsets to proceed and leaves those Pods in place. Plan shutdown of networking, logging and other node agents separately."], ['How is local data protected?', 'Identify temporary directories, local PVs and other persistent storage, then choose appropriate backup or migration. Rescheduling does not automatically move node-local data.'], ['How many nodes can be maintained together?', 'Use replica health, PDBs, zone distribution, spare capacity and recovery speed. Start with a small batch; a fixed percentage cannot replace workload checks.']]),
'container/helm': card('Helm / Kustomize', 'Helm packages templates, values and release revisions; resource rollback does not automatically reverse data or external effects.', 'Show rendered changes, artifact versions and rollback boundaries.',
'Review the final resources produced by templates or overlays. Pin chart dependencies and image versions, and record the effective values and override order.\n\nTreat migrations, hooks and CRDs according to their own lifecycles. Plan backward compatibility and compensation for changes that a release rollback cannot reverse.',
['Rendered resources reveal the actual change more directly than template syntax.', 'Record chart and image versions separately.', 'CRDs and hooks have additional lifecycle rules.', 'Manage environment values through controlled versioning.'],
['helm rollback does not undo every change.', 'Avoid manually duplicating values across several locations.'],
[['Helm or Kustomize?', 'Helm emphasizes parameterized templates and package releases; Kustomize composes and transforms declarative resources. Choose according to reuse and complexity, and review rendered output in either case.'], ['What can Helm roll back?', 'Primarily release-managed resource configuration. Data migrations, external effects and some special resources are not automatically reversed; design compatibility and compensation separately.'], ['How is values drift prevented?', 'Version environment inputs and override order, record effective deployment inputs and review rendered diffs. Inject sensitive values securely rather than leaving them in shell history.'], ['What if desired and actual state differ?', 'Identify defaulting, admission changes and manual edits before correcting declarations or runtime state. Raw YAML equality is insufficient, but meaningful drift must not be ignored.'], ['Why pin chart versions?', 'Different templates can render different resources from identical values. Pin versions and dependencies for reproducibility, then review and test upgrades as explicit changes.']]),
'container/quota': card('LimitRange and quotas', 'ResourceQuota limits namespace totals; LimitRange constrains or defaults individual resource declarations.', 'Distinguish tenant budgets, schedulable capacity and runtime isolation.',
'Use quotas to bound aggregate consumption and object counts, and LimitRanges to set appropriate per-object defaults and ranges. Admission policy does not reserve a suitable node.\n\nCalibrate defaults from workloads and verify storage capacity separately. Tenant isolation still needs access, network and data controls.',
['Quotas can constrain compute resources and object counts.', 'Available quota does not guarantee node capacity.', 'Calibrate defaults against actual workloads.', 'Tenant isolation also requires authorization, networking and data controls.'],
['Namespace quotas do not reserve exclusive node capacity.', 'Removing requests is not sound capacity management.'],
[['How do ResourceQuota and LimitRange differ?', 'Quota constrains namespace aggregates; LimitRange sets individual bounds and defaults. They support admission control but do not guarantee scheduling or application performance.'], ['What if requests are omitted?', 'Behavior depends on defaults, limits and admission configuration. If quota requirements remain unmet, creation may be rejected. Inspect the effective object and error.'], ['Why Pending despite available quota?', 'No node may satisfy requests, taints, affinity, topology or volume constraints. Namespace budget is not a promise of node-level resources.'], ['What if default requests are too high?', 'Schedulable capacity falls, costs rise and quotas can be consumed prematurely. Define workload classes and refine defaults from observed behavior.'], ['What matters for storage quotas?', 'PVC count, requested capacity and StorageClass-specific budgets, alongside backend capacity and reclamation. Quota is neither backup nor a provisioning guarantee.']]),
'net/dns': card('DNS fundamentals', 'DNS resolves names to records; connectivity also depends on caches, routes, ports and application state.', 'Validate resolution, connection, TLS and application response as separate steps.',
'Distinguish resolver behavior from transport and application behavior. Search domains and ndots can expand a lookup into several queries, while caching can retain positive or negative answers.\n\nLocate the failing resolution layer before changing settings. An address that accepts connections does not prove the service-name path works, and pinning an old address can break TLS or service changes.',
['A trailing dot identifies an absolute DNS name.', 'Positive and negative caches have expiration semantics.', 'Clients may maintain their own DNS caches.', 'Separate DNS failures from connection and application failures.'],
['Do not change every Pod DNS configuration before diagnosis.', 'Direct IP connectivity does not prove name-based access works.'],
[['How does ndots affect queries?', 'Names with fewer dots than the threshold may be tried with search domains first, adding queries and latency. Resolver behavior varies; observe real requests before changing the setting.'], ['How is intermittent CoreDNS behavior diagnosed?', 'Inspect query rates, latency, errors, resources, upstreams and node networking. Distinguish internal from external names before scaling or reconfiguring.'], ['How does DNS relate to discovery?', 'It is one discovery interface supplying addresses or service records. Connection management, balancing and health handling need additional mechanisms; records do not prove business health.'], ['What are cache trade-offs?', "Caching reduces query volume and latency, but a positive cache can serve an old address until its TTL expires. A negative cache can keep returning NXDOMAIN or no records of the requested type after a name or record is created. Identify the cache layer and check positive and negative TTLs and client behavior."], ['What if external names fail?', 'Compare inside/outside resolution, upstream responses and network policy. Check the domain and lookup chain; avoid arbitrary stale-IP fallbacks that break TLS or service changes.']]),
'net/coredns': card('CoreDNS', 'CoreDNS serves Kubernetes service records and can forward external queries to upstream resolvers.', 'Distinguish internal records, upstream forwarding and each caching layer.',
'The configured plugins determine how queries are resolved, cached and forwarded. Validate UDP and TCP paths and distinguish normal Services from headless backend discovery.\n\nTrace latency and errors through upstreams and client behavior. A cache hit rate alone cannot establish correctness, and restarting one component does not clear every cache.',
['Plugin configuration and ordering determine the processing chain.', 'DNS needs both UDP and TCP connectivity where applicable.', 'Headless and ordinary Services have different answer behavior.', 'Interpret cache hit rates alongside errors and stale results.'],
['Not every DNS delay is caused by CoreDNS CPU.', 'Opening UDP 53 alone can miss required TCP traffic.'],
[['Why can ndots amplify traffic?', 'External short names may be queried under several search domains before the absolute name. Validate with observed traffic or metrics, then assess absolute names and client resolver configuration.'], ['What does a headless Service return?', "A regular Service has A/AAAA records for its ClusterIP. A headless Service has no ClusterIP and can return multiple eligible endpoint addresses. For Services with selectors, endpoints normally need to be ready unless publishNotReadyAddresses is enabled. Clients must handle multiple addresses."], ['What if upstream DNS is slow?', 'Inspect forward targets, connectivity, timeouts, errors and concurrency. Use reliable upstreams and appropriate caching; indefinitely extending timeouts conceals dependency failure.'], ['Can NetworkPolicy break DNS?', 'Yes. Egress isolation may block Pod-to-DNS UDP/TCP, and DNS Pods can also be isolated. Verify actual address translation and plugin behavior.'], ['Why do old addresses remain after changes?', 'CoreDNS, node or client caches and API observation delays may contribute. Identify the layer and TTL; restarting one component does not clear the whole chain.']]),
'net/tls': card('TLS fundamentals', 'TLS protects transport confidentiality and integrity while authenticating peers through certificates; chain and hostname verification are essential.', 'Explain termination points, certificate validation and application authorization.',
'Encryption without trustworthy identity verification is insufficient. Validate certificate chains, names and validity, and identify every segment protected by TLS.\n\nMutual TLS authenticates both peers but does not decide which business operations they may perform. Manage keys and rotation, and keep authorization and application security as separate responsibilities.',
['Encryption and identity verification are both necessary.', 'Certificates and private keys serve different roles.', 'Termination points define which network segments are protected.', 'Map mTLS identities to explicit authorization policies.'],
['Disabling certificate verification is not a durable repair.', 'HTTPS does not automatically grant business access rights.'],
[['How is certificate expiry prevented?', 'Monitor certificates actually served at each termination point, rotate early and verify loading. Checking files or successful issuance does not prove the live endpoint switched.'], ['Can self-signed certificates be used?', 'Yes, with deliberately managed trust and name validation. Distribute and rotate trusted roots securely; self-signing is not a reason to disable verification.'], ['What does mTLS solve?', 'It authenticates both peers using certificates, often for workload identity. Separate authorization still decides which operations are permitted.'], ['How does HTTPS differ from HTTP?', 'TLS adds confidentiality, integrity and identity verification within its threat model. Application authorization, input validation and sensitive-log handling remain separate.'], ['What if a private key leaks?', 'Replace keys and certificates, revoke old credentials where supported and investigate distribution and use. Exposure of historical traffic depends on protocol and key exchange, not a universal rule.']]),
'net/cert': card('Certificate lifecycle', 'Certificate operations include issuance, distribution, loading, trust changes and revocation; verify rotation through real handshakes.', 'Use end-to-end handshake checks and rotation exercises as evidence.',
'A new certificate file is only one lifecycle step. Ensure the process loads it and clients trust the chain, names and validity period on the real access path.\n\nFor root rotation, distribute new trust before switching leaves, retain a deliberate overlap, then remove old trust. Test all instances, reconnects and long-lived connections.',
['Updated files do not prove a process reloaded its certificate.', 'SANs must match the DNS name or IP used by clients.', 'Root rotation needs a planned trust-overlap period.', 'Minimize private-key distribution.'],
['Successful issuance does not prove every endpoint serves the new certificate.', 'Not all clients reliably enforce revocation checks.'],
[['How is an incomplete chain diagnosed?', 'Inspect intermediates actually sent by the server and the client trust store and chain-building result. A browser may succeed using cached intermediates; test target clients.'], ['How can rotation avoid disruption?', "If the trust root changes, distribute the new trust to clients first. Then switch leaf certificates and keys, verify loading, and remove old trust according to plan. Test long-lived connections, reconnects and consistency across instances."], ['What limits revocation?', 'CRL/OCSP support and failure policies vary. Revocation may not immediately affect every client or connection; combine it with short lifetimes, key replacement and authorization controls.'], ['How do ingress TLS and service mTLS fit together?', 'Define external-to-ingress, ingress-to-service and service-to-service identity and encryption boundaries. TLS termination does not automatically protect subsequent internal hops.'], ['How are time or name errors diagnosed?', "First check the client clock and certificate validity period. For a name error, verify that SNI led the server to select the intended certificate and that the client reference identity matches the certificate SAN. Check a DNS SAN for a DNS name and an IP SAN for an IP address."]]),
};
